package org.apache.commons.math3.distribution;

import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for calculateNumericalVariance method in HypergeometricDistribution.
 * Since the method is protected, we use reflection to access it.
 */
public class HypergeometricDistribution_calculateNumericalVariance_TriageGen1Test {

    private static final double DELTA = 1e-12;

    /**
     * Helper method to invoke the protected method via reflection.
     */
    private double invokeCalculateNumericalVariance(HypergeometricDistribution dist) throws Exception {
        Method method = HypergeometricDistribution.class.getDeclaredMethod("calculateNumericalVariance");
        method.setAccessible(true);
        return (double) method.invoke(dist);
    }

    @Test
    public void testCalculateNumericalVariance_StandardCase() throws Exception {
        // N = 100, m = 20, n = 10
        // Variance = (10 * 20 * (100 - 10) * (100 - 20)) / (100 * 100 * (100 - 1))
        // Variance = (10 * 20 * 90 * 80) / (100 * 100 * 99)
        // Variance = 1440000 / 990000 = 1.454545454545...
        int N = 100;
        int m = 20;
        int n = 10;
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        double expected = (double) (n * m * (N - n) * (N - m)) / (N * N * (N - 1));
        double actual = invokeCalculateNumericalVariance(dist);

        Assert.assertEquals("Variance calculation failed for standard case", expected, actual, DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_SmallestValidCase() throws Exception {
        // Smallest N where N-1 > 0 is N=2. 
        // Let N=2, m=1, n=1
        // Variance = (1 * 1 * (2 - 1) * (2 - 1)) / (2 * 2 * (2 - 1)) = 1 / 4 = 0.25
        int N = 2;
        int m = 1;
        int n = 1;
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        double expected = 0.25;
        double actual = invokeCalculateNumericalVariance(dist);

        Assert.assertEquals("Variance calculation failed for minimal N", expected, actual, DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroVarianceCase_mIsZero() throws Exception {
        // If m = 0, variance should be 0
        int N = 100;
        int m = 0;
        int n = 10;
        // Note: Constructor might throw exception depending on implementation of m >= 0 requirement.
        // Based on hypergeometric logic, m can be 0.
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        double actual = invokeCalculateNumericalVariance(dist);
        Assert.assertEquals(0.0, actual, DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroVarianceCase_nIsZero() throws Exception {
        // If n = 0, variance should be 0
        int N = 100;
        int m = 20;
        int n = 0;
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        double actual = invokeCalculateNumericalVariance(dist);
        Assert.assertEquals(0.0, actual, DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroVarianceCase_nEqualsN() throws Exception {
        // If n = N, (N-n) = 0, so variance = 0
        int N = 50;
        int m = 10;
        int n = 50;
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        double actual = invokeCalculateNumericalVariance(dist);
        Assert.assertEquals(0.0, actual, DELTA);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroVarianceCase_mEqualsN() throws Exception {
        // If m = N, (N-m) = 0, so variance = 0
        int N = 50;
        int m = 50;
        int n = 10;
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        double actual = invokeCalculateNumericalVariance(dist);
        Assert.assertEquals(0.0, actual, DELTA);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructor_ThrowsException_NIsZero() {
        new HypergeometricDistribution(0, 5, 5);
    }

    @Test
    public void testGettersMatchConstructor() throws Exception {
        int N = 100;
        int m = 20;
        int n = 10;
        HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);

        Assert.assertEquals(N, dist.getPopulationSize());
        Assert.assertEquals(m, dist.getNumberOfSuccesses());
        Assert.assertEquals(n, dist.getSampleSize());
    }
}
